import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"ADR-0009: Why Notification is Decoupled","description":"","frontmatter":{},"headers":[],"relativePath":"adr/ADR-0009-why-notification-decoupled.md","filePath":"adr/ADR-0009-why-notification-decoupled.md","lastUpdated":1793381793000}`),a={name:`adr/ADR-0009-why-notification-decoupled.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="adr-0009-why-notification-is-decoupled" tabindex="-1">ADR-0009: Why Notification is Decoupled <a class="header-anchor" href="#adr-0009-why-notification-is-decoupled" aria-label="Permalink to “ADR-0009: Why Notification is Decoupled”">​</a></h1><ul><li>Status: Accepted</li><li>Date: 2026-10-31</li><li>Related: docs/guide/notification.md §8</li></ul><h2 id="background" tabindex="-1">Background <a class="header-anchor" href="#background" aria-label="Permalink to “Background”">​</a></h2><p>Notification channels (Webhook/SMTP/herald) depend on network and third-party availability; the recovery engine depends on local resources. Coupling them means: when offline, recovery is stuck on sends; channel failures amplify into system failures; <code>delivery_failed</code> re-triggering notifications creates an infinite self-excitation loop.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p>The Core Engine only produces structured <code>NotificationEvent</code>s (11 types, custos-model), handed to custos-notify via an EventEmitter callback; the notification engine handles rule matching, enqueueing (SQLite five-state queue), background delivery, exponential backoff, dead-lettering, dedup/aggregation; enqueueing and sending <strong>never block</strong> recovery (§8.1 acceptance); <code>notification.delivery_failed</code> goes only to the local log, constructively breaking the self-excitation loop. Persistence goes through the <code>NotificationQueue</code> port trait — notify does not reverse-depend on store/engine, the dependency graph stays acyclic.</p><h2 id="alternatives" tabindex="-1">Alternatives <a class="header-anchor" href="#alternatives" aria-label="Permalink to “Alternatives”">​</a></h2><ul><li><strong>Recovery engine sends inline</strong>: a slow channel slows recovery; a broken channel breaks recovery; offline events cannot be drained.</li><li><strong>Shared thread pool direct sends</strong>: no persistence, offline loses events; no retry semantics.</li></ul><h2 id="pros-and-cons" tabindex="-1">Pros and Cons <a class="header-anchor" href="#pros-and-cons" aria-label="Permalink to “Pros and Cons”">​</a></h2><p>Pros: during outages events all stay queued and drain after recovery (acceptance test offline.rs); channels are pluggable (local-log/webhook/smtp/herald share one Channel trait); sensitive-information governance (scrub) executes in one place. Cons: an extra queue state machine (Pending/Sending/Delivered/RetryScheduled/DeadLetter); end-to-end is at-least-once, relying on stable event ids + receiver-side deduplication.</p><h2 id="follow-up-impact" tabindex="-1">Follow-up Impact <a class="header-anchor" href="#follow-up-impact" aria-label="Permalink to “Follow-up Impact”">​</a></h2><ul><li>Webhook/SMTP/herald channels are added per this trait; new channels never touch the core.</li><li>CLI <code>notify status/retry</code> reads the queue; recovery and notification acceptance gates are separate.</li></ul>`,12)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};